/* =========================================================
   ATELIÉ DO ESTOFADO — script.js
   ========================================================= */
(() => {
  "use strict";

  document.documentElement.classList.add("js");

  /* =======================================================
     1) FOTOS — salve cada arquivo na pasta img/ (ao lado do index.html)
     ======================================================= */
  const IMAGENS = {
    // FOTOS REAIS (suas)
    antes: "data:image/jpeg;base64,",         // poltrona antiga e desgastada
    depois: "data:image/jpeg;base64,",       // poltrona bouclé creme (nova)
    servico2: "data:image/jpeg;base64,",   // sofá bege com almofadas terracota

    // IMAGENS GERADAS (provisórias): para trocar, salve sua foto com o mesmo nome em img/
    servico1: "data:image/jpeg;base64,",   // recorte do sofá sob medida
    servico3: "data:image/jpeg;base64,",   // poltrona antes | depois
    sofaVerde: "data:image/jpeg;base64,",// sofá recolorido em verde-esmeralda
    linho: "data:image/jpeg;base64,",         // textura de linho
    veludo: "data:image/jpeg;base64,",       // textura de veludo esmeralda
    couro: "data:image/jpeg;base64,"          // textura de couro caramelo
  };

  // Fotos reaproveitadas (mesmo arquivo em mais de um lugar)
  IMAGENS.hero = IMAGENS.depois;            // destaque do topo: poltrona bouclé creme
  IMAGENS.bannerFinal = IMAGENS.servico2;   // banner final: sofá creme com almofadas terracota

  // A galeria reaproveita as mesmas fotos
  IMAGENS.gal1 = IMAGENS.servico3;
  IMAGENS.gal2 = IMAGENS.servico2;
  IMAGENS.gal3 = IMAGENS.sofaVerde;
  IMAGENS.gal4 = IMAGENS.hero;

  // Liga os nomes usados no HTML aos nomes da lista acima
  const ALIASES = { srv1: "servico1", srv2: "servico2", srv3: "servico3", tecidoDestaque: "sofaVerde", cta: "bannerFinal" };
  const getImage = (key) => IMAGENS[key] ?? IMAGENS[ALIASES[key]] ?? "";

  /* ---------- Carregamento com fallback inteligente ---------- */
  const showFallback = (box, url, key) => {
    box.dataset.fallback = url ? `Salve a foto como ${url}` : `Defina IMAGENS.${key} no script.js`;
    box.classList.remove("has-img");
    box.classList.add("is-missing");
  };

  const applyImage = (img, key) => {
    const url = getImage(key);
    const box = img.closest(".media");
    box.classList.remove("has-img", "is-missing");

    img.onload = () => {
      box.classList.remove("is-missing");
      box.classList.add("has-img");
      // formato real da foto (a galeria ajusta a proporção para não cortar a peça)
      const r = img.naturalWidth / img.naturalHeight;
      box.dataset.shape = r > 1.15 ? "landscape" : r < 0.87 ? "portrait" : "square";
    };
    img.onerror = () => showFallback(box, url, key);

    if (!url) {
      img.removeAttribute("src");
      showFallback(box, url, key);
      return;
    }
    img.src = url;
    if (img.complete && img.naturalWidth > 0) img.onload(); // imagem já em cache
  };

  // Logo (cabeçalho e rodapé) embutida no código
  const LOGO = "data:image/png;base64,";
  document.querySelectorAll("img[data-logo]").forEach((img) => { img.src = LOGO; });

  document.querySelectorAll("img[data-img]").forEach((img) => applyImage(img, img.dataset.img));

  /* =======================================================
     2) WhatsApp
     ======================================================= */
  const WHATSAPP_NUMBER = "558196136379";
  const DEFAULT_MESSAGE = "Olá! Vim pelo site do Ateliê do Estofado e gostaria de solicitar um orçamento.";

  const buildWhatsAppLink = (message = DEFAULT_MESSAGE, phone = WHATSAPP_NUMBER) =>
    `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;

  const setupWhatsAppLink = (el) => {
    el.href = buildWhatsAppLink(el.dataset.message || DEFAULT_MESSAGE, el.dataset.phone || WHATSAPP_NUMBER);
    el.target = "_blank";
    el.rel = "noopener noreferrer";
  };

  document.querySelectorAll("[data-whatsapp]").forEach(setupWhatsAppLink);

  const anoEl = document.getElementById("ano");
  if (anoEl) anoEl.textContent = new Date().getFullYear();

  /* =======================================================
     3) Menu mobile (#menuToggle)
     ======================================================= */
  const menuToggle = document.getElementById("menuToggle");
  const menu = document.getElementById("menu");

  const setMenu = (open) => {
    menu.classList.toggle("is-open", open);
    menuToggle.setAttribute("aria-expanded", String(open));
    menuToggle.setAttribute("aria-label", open ? "Fechar menu" : "Abrir menu");
  };

  menuToggle.addEventListener("click", () => setMenu(!menu.classList.contains("is-open")));
  menu.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => setMenu(false)));
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && menu.classList.contains("is-open")) {
      setMenu(false);
      menuToggle.focus();
    }
  });
  window.matchMedia("(max-width: 959px)").addEventListener("change", (e) => {
    if (!e.matches) setMenu(false);
  });

  /* =======================================================
     4) Modais (comportamento comum)
     ======================================================= */
  const openDialog = (dialog) => {
    if (typeof dialog.showModal === "function") {
      dialog.showModal();
      document.body.classList.add("is-locked");
      return true;
    }
    return false;
  };

  document.querySelectorAll("dialog.modal").forEach((dialog) => {
    dialog.addEventListener("click", (e) => { if (e.target === dialog) dialog.close(); }); // clique no fundo
    dialog.addEventListener("close", () => { if (!document.querySelector("dialog.modal[open]")) document.body.classList.remove("is-locked"); });
    dialog.querySelectorAll("[data-close-modal]").forEach((btn) =>
      btn.addEventListener("click", () => dialog.close())
    );
  });

  /* =======================================================
     5) Modal comparativo Antes e Depois
     ======================================================= */
  const baModal = document.getElementById("ba-modal");
  const baItems = baModal.querySelectorAll(".ba-big__item");

  const openComparison = (focus = "") => {
    baItems.forEach((item) => item.classList.toggle("is-focus", item.dataset.view === focus));
    openDialog(baModal);
  };

  document.querySelectorAll(".ba-thumb").forEach((thumb) =>
    thumb.addEventListener("click", () => openComparison(thumb.dataset.view))
  );
  document.getElementById("ba-open").addEventListener("click", () => openComparison());

  /* =======================================================
     6) Modal de tecidos
     ======================================================= */
  const FABRICS = {
    linho: {
      nome: "Linho",
      descricao: "Fibra natural, leve e elegante. O linho traz sofisticação discreta e deixa o ambiente com aparência fresca e acolhedora.",
      composicao: "Fibra de linho pura ou misturada com algodão/viscose para mais resistência",
      toque: "Fresco, levemente texturizado",
      uso: "Sofás, poltronas, cortinas e almofadas em ambientes claros",
      cuidado: "Limpeza a seco ou aspiração regular; evite exposição prolongada ao sol",
    },
    veludo: {
      nome: "Veludo",
      descricao: "Macio, encorpado e com brilho sutil. O veludo valoriza a cor e dá presença às peças de destaque da sala.",
      composicao: "Poliéster de alta densidade (veludo liso ou texturizado), resistente ao uso diário",
      toque: "Aveludado, macio e confortável",
      uso: "Sofás, poltronas de destaque, cabeceiras e puffs",
      cuidado: "Escovar no sentido do tecido; limpar manchas rapidamente com pano úmido",
    },
    couro: {
      nome: "Couro",
      descricao: "Resistente e atemporal. O couro ganha personalidade com o uso e combina com ambientes clássicos ou contemporâneos.",
      composicao: "Couro legítimo ou couro ecológico, conforme o projeto e o orçamento",
      toque: "Firme, encorpado e aconchegante",
      uso: "Sofás, poltronas de leitura, cadeiras e escritórios",
      cuidado: "Hidratar periodicamente e limpar com pano macio levemente úmido",
    },
  };

  const fabricModal = document.getElementById("fabric-modal");
  const tabs = fabricModal.querySelectorAll("[data-tab]");
  const preview = document.getElementById("fabric-preview");
  const previewImg = document.getElementById("fabric-img");
  const els = {
    nome: document.getElementById("fabric-title"),
    desc: document.getElementById("fabric-desc"),
    composicao: document.getElementById("fabric-composicao"),
    toque: document.getElementById("fabric-toque"),
    uso: document.getElementById("fabric-uso"),
    cuidado: document.getElementById("fabric-cuidado"),
    cta: document.getElementById("fabric-cta"),
  };

  const renderFabric = (key) => {
    const f = FABRICS[key];
    if (!f) return;
    els.nome.textContent = f.nome;
    els.desc.textContent = f.descricao;
    els.composicao.textContent = f.composicao;
    els.toque.textContent = f.toque;
    els.uso.textContent = f.uso;
    els.cuidado.textContent = f.cuidado;
    preview.dataset.tone = key;
    previewImg.alt = `Amostra de ${f.nome.toLowerCase()}`;
    applyImage(previewImg, key);
    els.cta.dataset.message = `Olá! Quero agendar uma visita ao Ateliê do Estofado para ver o mostruário de ${f.nome.toLowerCase()}.`;
    setupWhatsAppLink(els.cta);
    tabs.forEach((tab) => tab.setAttribute("aria-pressed", String(tab.dataset.tab === key)));
  };

  const openFabric = (key = "linho") => {
    renderFabric(key);
    if (!openDialog(fabricModal)) window.open(els.cta.href, "_blank", "noopener");
  };

  document.querySelectorAll("[data-fabric]").forEach((btn) =>
    btn.addEventListener("click", () => openFabric(btn.dataset.fabric))
  );
  document.querySelectorAll("[data-open-fabrics]").forEach((btn) =>
    btn.addEventListener("click", () => openFabric("linho"))
  );
  tabs.forEach((tab) => tab.addEventListener("click", () => renderFabric(tab.dataset.tab)));

  /* =======================================================
     7) ORÇAMENTO PERSONALIZADO (Sob Medida e Reforma / Restauração)
     ======================================================= */
  const QUOTE_WHATSAPP = WHATSAPP_NUMBER; // mesmo número principal do site (troque aqui se quiser outro)
  const PHOTO_MAX_MB = 15;

  /* ---- ENVIO REAL DA FOTO (link na mensagem) ----
     O WhatsApp não aceita anexo por link. Para a foto chegar ao dono, ela é enviada
     a um serviço de imagens (ImgBB, gratuito) e o LINK vai dentro da mensagem.
     1) Crie a conta em https://imgbb.com  2) Pegue a chave em https://api.imgbb.com
     3) Cole a chave abaixo. Enquanto estiver vazio, vale o modo antigo (colar a foto). */
  const IMGBB_API_KEY = "36f49ab5f4e1ca8811a26a37da6d76ff";
  const PHOTO_EXPIRATION_SECONDS = 60 * 60 * 24 * 60; // a foto some do link após 60 dias (0 = nunca)
  const PHOTO_LINE = "*Tenho a foto do estofado — estou enviando aqui na conversa agora!*";

  /* ---------- Catálogo de opções (fonte única para os dois modais) ---------- */
  const MODELOS = [
    { grupo: "Sofás", itens: [
      "Sofá Retrátil e Reclinável", "Sofá Fixo / Living (Linhas Retas)", "Sofá de Canto / Em L", "Sofá Modular / Ilha",
      "Sofá Chaise (Com prolongamento)", "Sofá Chesterfield (Capitonê clássico)", "Sofá-Cama", "Sofá Curvo / Orgânico",
    ] },
    { grupo: "Outras peças", itens: [
      "Poltrona Decorativa / Giratória", "Poltrona do Papai (Reclinável)", "Cabeceira Estofada (Lisa, Ripada ou Modulados)",
      "Canto Alemão Sob Medida", "Puff / Banqueta / Recamier", "Outro modelo personalizado",
    ] },
  ];

  const TAMANHOS = [
    { grupo: "Sofás e peças grandes", itens: [
      "2 Lugares (1,60m a 1,80m)", "3 Lugares (2,00m a 2,30m)", "4 Lugares (2,50m a 2,90m)", "Gigante / Sala Ampla (Acima de 3,00m)",
    ] },
    { grupo: "Individual", itens: ["Poltrona / Individual (0,80m a 1,10m)"] },
    { grupo: "Cabeceiras (largura da cama)", itens: [
      "Cabeceira Solteiro (cerca de 0,88m)", "Cabeceira Casal (cerca de 1,38m)", "Cabeceira Queen (cerca de 1,58m)", "Cabeceira King (cerca de 1,93m)",
    ] },
    { grupo: "Outro", itens: ["Medida Totalmente Personalizada"] },
  ];

  const MOVEIS_REFORMA = [
    "Sofá Retrátil", "Sofá Fixo 2 ou 3 Lugares", "Sofá de Canto / Em L", "Sofá Chesterfield", "Poltrona Decorativa",
    "Cadeiras de Jantar (Informar quantidade)", "Cabeceira de Cama", "Canto Alemão", "Estofado Comercial / Clínica", "Outro",
  ];

  const TECIDOS = [
    { nome: "Linho (Natural ou Misto)", dica: "Sofisticado e fresco." },
    { nome: "Bouclé", dica: "Textura encorpada, moderna e aconchegante." },
    { nome: "Veludo", dica: "Toque macio e brilho elegante." },
    { nome: "Suede / Suede Amassado", dica: "Macio e ótimo custo-benefício." },
    { nome: "Couro Natural", dica: "Alta durabilidade e luxo." },
    { nome: "Couro Ecológico / Courvin / Napa", dica: "Fácil limpeza, ideal para clínicas e uso intenso." },
    { nome: "Acquablock / Impermeável", dica: "Resistente a líquidos e a áreas gourmet." },
    { nome: "Faktura / Sarja Peletizada", dica: "Resistente e de toque suave." },
    { nome: "Tecido Pet Friendly", dica: "Trama fechada, anti-unhas de gatos e cães." },
    { nome: "Chenille / Jacquard", dica: "Trama clássica e encorpada." },
    { nome: "Não sei ainda — quero orientação com mostruário", dica: "Sem problema: combinamos uma visita com o mostruário." },
  ];

  const CORES = [
    { nome: "Off-White / Creme", hex: "#F2EBDD" },
    { nome: "Areia / Bege", hex: "#D8C7A8" },
    { nome: "Fendi / Cinza Claro", hex: "#B9B0A5" },
    { nome: "Chumbo / Grafite", hex: "#4A4D50" },
    { nome: "Verde-Esmeralda / Musgo", hex: "#2F6B4F" },
    { nome: "Terracota / Telha", hex: "#C86D44" },
    { nome: "Caramelo / Conhaque", hex: "#A9622F" },
    { nome: "Azul-Marinho / Petróleo", hex: "#1F3A4D" },
    { nome: "Preto", hex: "#1A1A1A" },
  ];

  /* ---------- Utilidades ---------- */
  const makeOption = (text, value = text) => {
    const o = document.createElement("option");
    o.value = value;
    o.textContent = text;
    return o;
  };

  const fillSelect = (select, groups, placeholder) => {
    select.append(makeOption(placeholder, ""));
    groups.forEach((g) => {
      if (typeof g === "string") { select.append(makeOption(g)); return; }
      const og = document.createElement("optgroup");
      og.label = g.grupo;
      g.itens.forEach((t) => og.append(makeOption(t)));
      select.append(og);
    });
  };

  const fmtMeters = (n) => `${n.toFixed(2).replace(".", ",")} m`;
  const clean = (s) => (s || "").replace(/\s+/g, " ").trim();

  /* ---------- Erros de campo ---------- */
  const controlOf = (field) => field.querySelector("select, input[type=text], textarea") || field.querySelector("input:not([type=file]), button");

  const clearFieldError = (field) => {
    field.classList.remove("has-error");
    field.querySelector(":scope > .field__error")?.remove();
    field.querySelectorAll("[aria-invalid]").forEach((c) => c.removeAttribute("aria-invalid"));
  };

  const setFieldError = (form, name, message) => {
    const field = form.querySelector(`[data-field="${name}"]`);
    if (!field) return null;
    clearFieldError(field);
    field.classList.add("has-error");
    const p = document.createElement("p");
    p.className = "field__error";
    p.setAttribute("role", "alert");
    p.textContent = message;
    field.append(p);
    field.querySelectorAll("select, input:not([type=file]):not([type=checkbox]), textarea").forEach((c) => c.setAttribute("aria-invalid", "true"));
    return field;
  };

  const clearAllErrors = (form) => form.querySelectorAll(".field.has-error").forEach(clearFieldError);

  /* ---------- Seletor visual de cores + campo livre ---------- */
  const initColorPicker = (form) => {
    const wrap = form.querySelector("[data-color-picker]");
    const input = wrap.closest(".field").querySelector('input[type="text"]');
    const dots = CORES.map((c) => {
      const b = document.createElement("button");
      b.type = "button";
      b.className = "dot";
      b.setAttribute("aria-pressed", "false");
      b.dataset.name = c.nome;
      b.innerHTML = '<span class="dot__color"></span><span class="dot__name"></span>';
      b.querySelector(".dot__color").style.background = c.hex;
      b.querySelector(".dot__name").textContent = c.nome;
      wrap.append(b);
      return b;
    });
    const sync = () => dots.forEach((d) => d.setAttribute("aria-pressed", String(clean(input.value).toLowerCase() === d.dataset.name.toLowerCase())));
    dots.forEach((d) => d.addEventListener("click", () => {
      input.value = d.dataset.name;
      sync();
      clearFieldError(input.closest(".field"));
    }));
    input.addEventListener("input", sync);
    return { input, sync };
  };

  /* ---------- Select de tecido com dica ---------- */
  const initFabricSelect = (form) => {
    const select = form.querySelector('select[data-fill="fabrics"]');
    const hint = form.querySelector("[data-fabric-hint]");
    fillSelect(select, TECIDOS.map((t) => t.nome), "Selecione o tecido…");
    select.addEventListener("change", () => {
      const t = TECIDOS.find((x) => x.nome === select.value);
      hint.textContent = t ? t.dica : "";
    });
    return select;
  };

  /* ---------- Anexo de foto com miniatura (FileReader) ---------- */
  const initUpload = (form) => {
    const root = form.querySelector("[data-upload]");
    const input = root.querySelector('input[type="file"]');
    const drop = root.querySelector(".upload__drop");
    const preview = root.querySelector(".upload__preview");
    const thumb = preview.querySelector("img");
    const nameEl = preview.querySelector(".upload__name");
    const msg = root.querySelector(".upload__msg");
    const state = { file: null };

    const showMsg = (text) => { msg.textContent = text; msg.hidden = !text; };
    const reset = () => {
      state.file = null;
      input.value = "";
      thumb.removeAttribute("src");
      preview.hidden = true;
    };

    const handle = (file) => {
      showMsg("");
      if (!file) { reset(); return; }
      if (!file.type.startsWith("image/")) { reset(); showMsg("Esse arquivo não é uma imagem. Escolha uma foto (JPG, PNG ou WEBP)."); return; }
      if (file.size > PHOTO_MAX_MB * 1024 * 1024) { reset(); showMsg(`A foto passa de ${PHOTO_MAX_MB} MB. Escolha uma foto menor.`); return; }
      const reader = new FileReader();
      reader.onload = () => {
        state.file = file;
        thumb.src = reader.result;
        nameEl.textContent = file.name;
        preview.hidden = false;
      };
      reader.onerror = () => { reset(); showMsg("Não foi possível ler essa foto. Tente outra."); };
      reader.readAsDataURL(file);
    };

    input.addEventListener("change", () => handle(input.files[0]));
    preview.querySelector(".upload__remove").addEventListener("click", () => { reset(); showMsg(""); input.focus(); });

    ["dragenter", "dragover"].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.add("is-drag"); }));
    ["dragleave", "drop"].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.remove("is-drag"); }));
    drop.addEventListener("drop", (e) => handle(e.dataTransfer?.files?.[0]));

    return { hasPhoto: () => Boolean(state.file), getFile: () => state.file };
  };

  /* ---------- Envio ---------- */
  const buildQuoteLink = (message) => `https://wa.me/${QUOTE_WHATSAPP}?text=${encodeURIComponent(message)}`;

  /* A foto não vai por link (wa.me só aceita texto). Caminhos possíveis:
     1) celular: menu de compartilhar do aparelho, que envia foto + texto juntos;
     2) computador: a foto é copiada e o cliente só cola (Ctrl+V) na conversa. */
  const toPngBlob = (file) => new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const c = document.createElement("canvas");
      c.width = img.naturalWidth; c.height = img.naturalHeight;
      c.getContext("2d").drawImage(img, 0, 0);
      c.toBlob((b) => { URL.revokeObjectURL(url); b ? resolve(b) : reject(new Error("png")); }, "image/png");
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("img")); };
    img.src = url;
  });

  const copyPhoto = async (file) => {
    try {
      if (!navigator.clipboard?.write || typeof ClipboardItem === "undefined") return false;
      const blob = file.type === "image/png" ? file : await toPngBlob(file);
      await navigator.clipboard.write([new ClipboardItem({ "image/png": blob })]);
      return true;
    } catch { return false; }
  };

  const sharePhoto = async (file, message) => {
    const data = { files: [file], text: message };
    if (!(navigator.share && navigator.canShare && navigator.canShare(data))) return "unsupported";
    try { await navigator.share(data); return "shared"; }
    catch (err) { return err && err.name === "AbortError" ? "aborted" : "failed"; }
  };

  const renderNotice = (form, text, actions = []) => {
    const notice = form.querySelector(".quote__notice");
    notice.replaceChildren();
    const p = document.createElement("p");
    p.textContent = text;
    notice.append(p);
    if (actions.length) {
      const row = document.createElement("div");
      row.className = "notice__actions";
      actions.forEach((a) => {
        const el = document.createElement(a.href ? "a" : "button");
        el.textContent = a.label;
        if (a.href) { el.href = a.href; el.target = "_blank"; el.rel = "noopener noreferrer"; }
        else { el.type = "button"; el.addEventListener("click", a.onClick); }
        row.append(el);
      });
      notice.append(row);
    }
    notice.hidden = false;
    notice.scrollIntoView({ behavior: "smooth", block: "nearest" });
  };

  /* Reduz a foto (lado maior 1600px, JPEG) para subir rápido, inclusive no 4G */
  const shrinkPhoto = (file, max = 1600) => new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const k = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
      const c = document.createElement("canvas");
      c.width = Math.round(img.naturalWidth * k); c.height = Math.round(img.naturalHeight * k);
      c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
      c.toBlob((b) => { URL.revokeObjectURL(url); resolve(b || file); }, "image/jpeg", 0.86);
    };
    img.onerror = () => { URL.revokeObjectURL(url); resolve(file); };
    img.src = url;
  });

  const uploadPhoto = async (file) => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 45000);
    try {
      const body = new FormData();
      body.append("image", await shrinkPhoto(file), "foto-estofado.jpg");
      const qs = `key=${encodeURIComponent(IMGBB_API_KEY)}` + (PHOTO_EXPIRATION_SECONDS ? `&expiration=${PHOTO_EXPIRATION_SECONDS}` : "");
      const res = await fetch(`https://api.imgbb.com/1/upload?${qs}`, { method: "POST", body, signal: ctrl.signal });
      const json = await res.json();
      return json?.success ? (json.data.url_viewer || json.data.url) : null;
    } catch { return null; }
    finally { clearTimeout(timer); }
  };

  const finishSend = async (form, message, file) => {
    // Com a chave configurada: sobe a foto e manda o LINK dela no WhatsApp
    if (file && IMGBB_API_KEY) {
      const btn = form.querySelector('button[type="submit"]');
      const label = btn.innerHTML;
      btn.disabled = true;
      btn.textContent = "Enviando a foto…";
      const win = window.open("", "_blank"); // abre já (dentro do clique) para o navegador não bloquear
      const url = await uploadPhoto(file);
      btn.disabled = false;
      btn.innerHTML = label;
      if (url) {
        const finalLink = buildQuoteLink(message.replace(PHOTO_LINE, `*Foto do estofado:* ${url}`));
        if (win) win.location.href = finalLink;
        renderNotice(form, "Pronto! A foto foi enviada junto: o link dela vai dentro da mensagem do WhatsApp. É só tocar em enviar. ✅", [{ label: "A janela não abriu? Abrir o WhatsApp", href: finalLink }]);
        return;
      }
      win?.close();
      renderNotice(form, "Não conseguimos enviar a foto agora (verifique a internet). Vamos seguir pelo modo manual:");
    }
    const link = buildQuoteLink(message);
    const openLink = { label: "Abrir o WhatsApp (só o texto)", href: link };

    if (!file) {
      renderNotice(form, "Abrimos o WhatsApp com o seu orçamento. É só tocar em enviar. ✅", [{ label: "A janela não abriu? Abrir novamente", href: link }]);
      window.open(link, "_blank", "noopener");
      return;
    }

    const doShare = async () => {
      const r = await sharePhoto(file, message);
      if (r === "shared") {
        renderNotice(form, "No menu que abriu, escolha o WhatsApp e depois o contato do Ateliê do Estofado. A foto e o orçamento seguem juntos. 📸");
        return true;
      }
      return r;
    };

    // Celular: compartilhamento nativo (foto + texto na mesma mensagem)
    if (window.matchMedia("(pointer: coarse)").matches) {
      const r = await doShare();
      if (r === true) return;
      renderNotice(
        form,
        r === "aborted" ? "O envio foi cancelado. Toque abaixo para tentar de novo." : "Não foi possível enviar a foto junto. Tente de novo ou abra o WhatsApp só com o texto e anexe a foto na conversa (ícone de clipe ou “+”).",
        [{ label: "Enviar foto + orçamento", onClick: async () => { const x = await doShare(); if (x !== true) renderNotice(form, "Seu navegador não permitiu. Abra o WhatsApp e anexe a foto na conversa.", [openLink]); } }, openLink]
      );
      return;
    }

    // Computador: copia a foto e abre o WhatsApp; o cliente cola na conversa
    const copied = await copyPhoto(file);
    window.open(link, "_blank", "noopener");
    renderNotice(
      form,
      copied
        ? "Foto copiada! Na conversa do WhatsApp que abriu, clique na caixa de mensagem e cole com Ctrl+V (ou ⌘+V no Mac). Depois é só enviar. 📸"
        : "Abrimos o WhatsApp com o orçamento. Não conseguimos copiar a foto automaticamente: anexe-a na conversa (ícone de clipe) e envie. 📸",
      copied ? [{ label: "Copiar a foto novamente", onClick: async () => { const ok = await copyPhoto(file); renderNotice(form, ok ? "Foto copiada de novo. Cole na conversa com Ctrl+V." : "Não foi possível copiar. Anexe a foto pelo clipe do WhatsApp.", [openLink]); } }, { label: "A janela não abriu? Abrir o WhatsApp", href: link }]
             : [{ label: "A janela não abriu? Abrir o WhatsApp", href: link }]
    );
  };

  const focusFirstError = (form, names) => {
    const first = names.map((n) => form.querySelector(`[data-field="${n}"]`)).find(Boolean);
    if (!first) return;
    first.scrollIntoView({ behavior: "smooth", block: "center" });
    controlOf(first)?.focus({ preventScroll: true });
  };

  const readDims = (form) => {
    const get = (n) => {
      const raw = form.elements[n].value;
      return raw === "" ? null : parseFloat(raw);
    };
    return { largura: get("largura"), profundidade: get("profundidade"), altura: get("altura") };
  };

  /* ---------- Modal 1: Fabricação sob medida ---------- */
  const makeModal = document.getElementById("quote-make");
  const fixModal = document.getElementById("quote-fix");
  const choiceModal = document.getElementById("quote-choice");

  const setupMake = () => {
    const form = document.getElementById("form-make");
    fillSelect(form.elements.model, MODELOS, "Selecione o modelo…");
    fillSelect(form.elements.tamanho, TAMANHOS, "Selecione o tamanho…");
    initFabricSelect(form);
    const color = initColorPicker(form);
    const upload = initUpload(form);

    form.addEventListener("input", (e) => { const f = e.target.closest(".field"); if (f) clearFieldError(f); });
    form.addEventListener("change", (e) => { const f = e.target.closest(".field"); if (f) clearFieldError(f); });

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearAllErrors(form);
      const errors = [];
      const fail = (name, msg) => { setFieldError(form, name, msg); errors.push(name); };
      const d = readDims(form);

      if (!form.elements.model.value) fail("model", "Escolha o tipo e o modelo do estofado.");
      if (!form.elements.tamanho.value) fail("tamanho", "Escolha um tamanho de referência.");
      const bad = Object.entries(d).find(([, v]) => v !== null && (Number.isNaN(v) || v < 0.2 || v > 9.99));
      if (bad) fail("dims", "Use medidas entre 0,20 e 9,99 metros.");
      else if (form.elements.tamanho.value.startsWith("Medida Totalmente") && d.largura === null) fail("dims", "Para medida personalizada, informe ao menos a largura.");
      if (!form.elements.fabric.value) fail("fabric", "Escolha o tecido ou marque “Não sei ainda”.");
      if (!clean(color.input.value)) fail("color", "Toque numa cor ou digite a cor desejada.");

      if (errors.length) { focusFirstError(form, errors); return; }

      const lines = [
        "*ORÇAMENTO — ATELIÊ DO ESTOFADO*",
        "",
        "• *Tipo de serviço:* Fabricação sob medida",
        `• *Modelo:* ${form.elements.model.value}`,
        `• *Tamanho:* ${form.elements.tamanho.value}`,
      ];
      const dimLines = [["Largura", d.largura], ["Profundidade", d.profundidade], ["Altura", d.altura]].filter(([, v]) => v !== null);
      if (dimLines.length) lines.push(...dimLines.map(([n, v]) => `     - ${n}: ${fmtMeters(v)}`));
      lines.push(`• *Tecido:* ${form.elements.fabric.value}`, `• *Cor:* ${clean(color.input.value)}`);
      const notes = clean(form.elements.notes.value);
      if (notes) lines.push(`• *Observações:* ${notes}`);
      if (upload.hasPhoto()) lines.push("", PHOTO_LINE);

      finishSend(form, lines.join("\n"), upload.getFile());
    });
  };

  /* ---------- Modal 2: Reforma / Restauração ---------- */
  const setupFix = () => {
    const form = document.getElementById("form-fix");
    fillSelect(form.elements.movel, MOVEIS_REFORMA, "Selecione o móvel…");
    const fabricSel = initFabricSelect(form);
    const color = initColorPicker(form);
    const upload = initUpload(form);
    const kindChips = form.querySelectorAll("[data-kind]");
    const svcBoxes = [...form.querySelectorAll('input[name="svc"]')];
    const trocaTecido = svcBoxes[0];

    const setKind = (kind) => kindChips.forEach((c) => c.setAttribute("aria-pressed", String(c.dataset.kind === kind)));
    kindChips.forEach((c) => c.addEventListener("click", () => setKind(c.dataset.kind)));
    form._setKind = setKind;

    const isChairs = () => form.elements.movel.value.startsWith("Cadeiras");
    const syncRequired = () => {
      form.querySelectorAll(".req-fabric").forEach((el) => { el.hidden = !trocaTecido.checked; });
      form.querySelector(".req-qty").hidden = !isChairs();
    };
    trocaTecido.addEventListener("change", syncRequired);
    form.elements.movel.addEventListener("change", syncRequired);

    form.addEventListener("input", (e) => { const f = e.target.closest(".field"); if (f) clearFieldError(f); });
    form.addEventListener("change", (e) => { const f = e.target.closest(".field"); if (f) clearFieldError(f); });

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearAllErrors(form);
      const errors = [];
      const fail = (name, msg) => { setFieldError(form, name, msg); errors.push(name); };
      const services = svcBoxes.filter((c) => c.checked).map((c) => c.value);
      const measures = clean(form.elements.measures.value);

      if (!form.elements.movel.value) fail("movel", "Escolha qual móvel será reformado.");
      if (!services.length) fail("services", "Marque ao menos um serviço necessário.");
      if (trocaTecido.checked && !fabricSel.value) fail("fabric", "Escolha o novo tecido ou marque “Não sei ainda”.");
      if (trocaTecido.checked && !clean(color.input.value)) fail("color", "Toque numa cor ou digite a cor desejada.");
      if (isChairs() && !measures) fail("measures", "Informe a quantidade de cadeiras (ex.: 6 cadeiras).");

      if (errors.length) { focusFirstError(form, errors); return; }

      const kind = form.querySelector('[data-kind][aria-pressed="true"]')?.dataset.kind || "Reforma";
      const lines = [
        "*ORÇAMENTO — ATELIÊ DO ESTOFADO*",
        "",
        `• *Tipo de serviço:* ${kind} de estofado`,
        `• *Móvel:* ${form.elements.movel.value}`,
        "• *Serviços necessários:*",
        ...services.map((s) => `     - ${s}`),
      ];
      if (fabricSel.value) lines.push(`• *Novo tecido:* ${fabricSel.value}`);
      if (clean(color.input.value)) lines.push(`• *Nova cor:* ${clean(color.input.value)}`);
      if (measures) lines.push(`• *Medidas / Quantidade:* ${measures}`);
      const notes = clean(form.elements.notes.value);
      if (notes) lines.push(`• *Observações:* ${notes}`);
      if (upload.hasPhoto()) lines.push("", PHOTO_LINE);

      finishSend(form, lines.join("\n"), upload.getFile());
    });
  };

  setupMake();
  setupFix();

  /* ---------- Gatilhos de abertura ---------- */
  const openQuote = (type, kind) => {
    if (type === "fix" && kind) document.getElementById("form-fix")._setKind(kind);
    const target = type === "make" ? makeModal : type === "fix" ? fixModal : choiceModal;
    if (target !== choiceModal && choiceModal.open) choiceModal.close();
    target.querySelectorAll(".quote__notice").forEach((n) => { n.hidden = true; });
    if (!openDialog(target) && !target.open) window.open(buildQuoteLink("Olá! Vim pelo site do Ateliê do Estofado e gostaria de solicitar um orçamento."), "_blank", "noopener");
    target.querySelector(".modal__inner")?.scrollTo?.(0, 0);
    target.scrollTop = 0;
  };

  document.querySelectorAll("[data-quote-open]").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.preventDefault();
      openQuote(el.dataset.quoteOpen, el.dataset.quoteKind);
    })
  );

  /* =======================================================
     8) Animação de entrada (IntersectionObserver)
     ======================================================= */
  const revealItems = document.querySelectorAll(".reveal");

  if ("IntersectionObserver" in window) {
    const observer = new IntersectionObserver(
      (entries, obs) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            obs.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.15, rootMargin: "0px 0px -40px 0px" }
    );
    revealItems.forEach((el) => observer.observe(el));
  } else {
    revealItems.forEach((el) => el.classList.add("is-visible"));
  }
})();